{"name": "conf-canon", "type": "module", "private": true, "scripts": {"test": "node --test test/*.test.js"}}
import { spawnSync } from 'node:child_process'
import assert from 'node:assert/strict'
import { test } from 'node:test'
import { fileURLToPath } from 'node:url'

const cli = fileURLToPath(new URL('../src/cli.js', import.meta.url))

function run(argv, stdin = '') {
  const result = spawnSync(process.execPath, [cli, ...argv], { encoding: 'utf8', input: stdin })
  return { code: result.status, out: result.stdout, err: result.stderr }
}

test('a scalar assignment becomes one JSON member', () => {
  assert.deepEqual(run(['json'], 'a = 1\n'), { code: 0, out: '{\n  "a": 1\n}\n', err: '' })
})

test('members print in ascending key order', () => {
  assert.equal(run(['json'], 'b = 1\na = 2\n').out, '{\n  "a": 2,\n  "b": 1\n}\n')
})

test('a basic string decodes its escapes', () => {
  assert.equal(run(['json'], 'a = "x\\ty"\n').out, '{\n  "a": "x\\ty"\n}\n')
})

test('a literal string keeps its backslashes', () => {
  assert.equal(run(['json'], "a = 'x\\ty'\n").out, '{\n  "a": "x\\\\ty"\n}\n')
})

test('booleans are booleans', () => {
  assert.equal(run(['json'], 'a = true\nb = false\n').out, '{\n  "a": true,\n  "b": false\n}\n')
})

test('an integer may carry underscore separators', () => {
  assert.equal(run(['json'], 'a = 1_000\n').out, '{\n  "a": 1000\n}\n')
})

test('an array holds its items in order', () => {
  assert.equal(run(['json'], 'a = [1, 2]\n').out, '{\n  "a": [\n    1,\n    2\n  ]\n}\n')
})

test('a table header nests the keys under it', () => {
  assert.equal(run(['json'], '[s]\na = 1\n').out, '{\n  "s": {\n    "a": 1\n  }\n}\n')
})

test('a dotted header nests two levels', () => {
  assert.equal(run(['json'], '[s.t]\na = 1\n').out, '{\n  "s": {\n    "t": {\n      "a": 1\n    }\n  }\n}\n')
})

test('a doubled header appends to an array of tables', () => {
  assert.equal(run(['json'], '[[i]]\na = 1\n[[i]]\na = 2\n').out, '{\n  "i": [\n    {\n      "a": 1\n    },\n    {\n      "a": 2\n    }\n  ]\n}\n')
})

test('comments and blank lines are ignored', () => {
  assert.equal(run(['json'], '# note\n\na = 1 # tail\n').out, '{\n  "a": 1\n}\n')
})

test('an empty document is an empty object', () => {
  assert.deepEqual(run(['json'], ''), { code: 0, out: '{}\n', err: '' })
})

test('keys list every path with its type', () => {
  assert.equal(run(['keys'], '[s]\na = 1\nb = "x"\n').out, 's table\ns.a integer\ns.b string\n')
})

test('keys tell an integer from a float', () => {
  assert.equal(run(['keys'], 'a = 1\nb = 1.5\n').out, 'a integer\nb float\n')
})

test('a key defined twice is rejected', () => {
  const result = run(['json'], 'a = 1\na = 2\n')
  assert.equal(result.code, 2)
  assert.equal(result.out, '')
  assert.equal(result.err, 'error: line 2: key a is defined twice\n')
})

test('a table header used twice is rejected', () => {
  assert.equal(run(['json'], '[s]\n[s]\n').err, 'error: line 2: table s is defined twice\n')
})

test('a value that parses as nothing is rejected', () => {

#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

process.stderr.write('error: not implemented\n')
process.exit(1)
test('a value that parses as nothing is rejected', () => {
  assert.equal(run(['json'], 'a = nope\n').err, 'error: line 1: invalid value nope\n')
})

test('an unknown mode is rejected', () => {
  const result = run(['toml'], '')
  assert.equal(result.code, 2)
  assert.equal(result.err, 'error: usage: cli.js json|keys\n')
})
{
  "id": "code:conf-canon",
  "tier": 5,
  "domain": "parsing",
  "title": "Turn a configuration document into canonical JSON",
  "prompt": "`src/cli.js` is the program; how the work is split across other files under `src/` is up to you. It takes exactly one argument, `json` or `keys`, and reads a configuration document from standard input. Split the input on newlines and drop the empty tail a trailing newline leaves; every directive fits on one line. Exit 0 whenever the document parses.\n\nA line whose first character that is not a space or a tab is `#` or `;`, and a line holding only spaces and tabs, contributes nothing. Elsewhere a `#` or a `;` outside a quoted string ends the line, and what follows it is ignored; a `#` that a value runs into without whitespace before it is part of that value's text and makes it invalid.\n\nA name is a bare word of one or more of the characters `A` to `Z`, `a` to `z`, `0` to `9`, `_` and `-`, or a quoted string. A dotted name is names joined by `.`, with spaces and tabs allowed around each `.`.\n\nA line beginning with `[` is a header. `[name]` makes that table current, creating the tables on the way; when the name already holds anything other than a table the reason is `<path> is not a table`, and otherwise a table a header already made current may not be named by a second `[name]` header, though a table that only came into being on the way to a deeper one, or from a dotted key, still may. `[[name]]` appends a fresh table to the array of tables at that name, creating it when it is absent, and makes that fresh table current; when the name already holds anything other than an array of tables the reason is `<path> is not an array of tables`. Walking through an array of tables uses its last element. Anything but spaces, tabs and a comment after the closing bracket is an error.\n\nEvery other line is `<dotted name> = <value>`, assigning inside the current table, creating the tables the dots walk through. A name already holding anything may not be assigned again, and a dot may not walk through a name that holds something other than a table or an array of table