#!/usr/bin/env node
import { readFileSync } from 'node:fs'
import { parseDocument } from './parser.js'
import { toJson, toKeys } from './output.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
let out
try {
  const root = parseDocument(readFileSync(0, 'utf8'))
  out = args[0] === 'json' ? toJson(root) : toKeys(root)
} catch (e) {
  if (e && e.isConfigError) {
    process.stderr.write(`error: line ${e.line}: ${e.message}\n`)
    process.exit(2)
  }
  throw e
}
process.stdout.write(out)
