function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < x.length && i < y.length; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedKeys = (map) => [...map.keys()].sort(cmp)

function render(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  switch (n.t) {
    case 'table': {
      const ks = sortedKeys(n.map)
      if (!ks.length) return '{}'
      return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + render(n.map.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
    }
    case 'array':
      if (!n.items.length) return '[]'
      return '[\n' + n.items.map((i) => pad + render(i, ind + 1)).join(',\n') + '\n' + end + ']'
    case 'integer': return n.v.toString()
    default: return JSON.stringify(n.v)
  }
}
export const toJson = (root) => render(root, 0) + '\n'

export function toKeys(root) {
  const lines = []
  const walk = (n, path) => {
    if (n.t === 'table') {
      for (const k of sortedKeys(n.map)) {
        const p = path === null ? k : path + '.' + k
        lines.push(p + ' ' + n.map.get(k).t)
        walk(n.map.get(k), p)
      }
    } else if (n.t === 'array') {
      n.items.forEach((it, i) => {
        const p = path + '[' + i + ']'
        lines.push(p + ' ' + it.t)
        walk(it, p)
      })
    }
  }
  walk(root, null)
  return lines.map((l) => l + '\n').join('')
}
