const table = () => ({ t: 'table', map: new Map(), header: false })

class LineParser {
  constructor(s) { this.s = s; this.i = 0 }
  fail(msg) { const e = new Error(msg); e.isConfigError = true; throw e }
  ws() { while (this.s[this.i] === ' ' || this.s[this.i] === '\t') this.i++ }
  // true when only a comment or nothing remains
  atEnd() { this.ws(); const c = this.s[this.i]; return c === undefined || c === '#' || c === ';' }
  peek() { return this.s[this.i] }

  name() {
    const c = this.s[this.i]
    if (c === '"') return this.basic()
    if (c === "'") return this.literal()
    const m = /^[A-Za-z0-9_-]+/.exec(this.s.slice(this.i))
    if (!m) this.fail('expected a name')
    this.i += m[0].length
    return m[0]
  }
  dotted() {
    const out = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.s[this.i] !== '.') { this.i = save; return out }
      this.i++
      this.ws()
      out.push(this.name())
    }
  }
  basic() {
    this.i++
    let r = ''
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) this.fail('unterminated string')
      this.i++
      if (c === '"') return r
      if (c !== '\\') { r += c; continue }
      const e = this.s[this.i]
      if (e === undefined) this.fail('unterminated string')
      this.i++
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (e in map) r += map[e]
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9a-fA-F]{4}$/.test(h)) this.fail('invalid escape \\u')
        r += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else {
        const cp = String.fromCodePoint(this.s.codePointAt(this.i - 1))
        this.fail('invalid escape \\' + cp)
      }
    }
  }
  literal() {
    const j = this.s.indexOf("'", this.i + 1)
    if (j < 0) this.fail('unterminated string')
    const r = this.s.slice(this.i + 1, j)
    this.i = j + 1
    return r
  }

  value() {
    this.ws()
    const c = this.s[this.i]
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') this.fail('expected a value')
    if (c === '"') return { t: 'string', v: this.basic() }
    if (c === "'") return { t: 'string', v: this.literal() }
    if (c === '[') return this.array()
    if (c === '{') return this.inline()
    const m = /^[^\s,\]};]*/.exec(this.s.slice(this.i))
    const w = m[0]
    this.i += w.length
    if (w === 'true') return { t: 'boolean', v: true }
    if (w === 'false') return { t: 'boolean', v: false }
    const int = '[+-]?\\d+(?:_\\d+)*'
    if (new RegExp('^' + int + '$').test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '')) }
    if (new RegExp('^' + int + '(?:\\.\\d+(?:_\\d+)*(?:[eE][+-]?\\d+(?:_\\d+)*)?|[eE][+-]?\\d+(?:_\\d+)*)$').test(w)) {
      return { t: 'float', v: Number(w.replace(/_/g, '')) }
    }
    this.fail('invalid value ' + w)
  }
  array() {
    this.i++
    const items = []
    if (this.atEnd()) this.fail('unterminated array')
    if (this.peek() === ']') { this.i++; return { t: 'array', items, aot: false } }
    for (;;) {
      items.push(this.value())
      if (this.atEnd()) this.fail('unterminated array')
      const c = this.peek()
      if (c === ']') { this.i++; break }
      if (c !== ',') this.fail('unterminated array')
      this.i++
      if (this.atEnd()) this.fail('unterminated array')
      if (this.peek() === ']') { this.i++; break }
    }
    return { t: 'array', items, aot: false }
  }
  inline() {
    this.i++
    const tbl = table()
    if (this.atEnd()) this.fail('unterminated inline table')
    if (this.peek() === '}') { this.i++; return tbl }
    for (;;) {
      this.ws()
      const names = this.dotted()
      this.ws()
      if (this.atEnd()) this.fail('unterminated inline table')
      if (this.peek() !== '=') this.fail('expected = in an inline table')
      this.i++
      const v = this.value()
      assign(tbl, [], names, v, this)
      if (this.atEnd()) this.fail('unterminated inline table')
      const c = this.peek()
      if (c === '}') { this.i++; break }
      if (c !== ',') this.fail('unterminated inline table')
      this.i++
      if (this.atEnd()) this.fail('unterminated inline table')
    }
    return tbl
  }
}

function descend(node, names, upto, base, p, creating) {
  // walk names[0..upto) from node; returns the table reached
  let cur = node
  for (let k = 0; k < upto; k++) {
    const path = [...base, ...names.slice(0, k + 1)].join('.')
    let nx = cur.map.get(names[k])
    if (!nx) {
      nx = table()
      cur.map.set(names[k], nx)
    } else if (nx.t === 'array' && nx.aot) {
      nx = nx.items[nx.items.length - 1]
    } else if (nx.t !== 'table') p.fail(path + ' is not a table')
    cur = nx
  }
  return cur
}

function assign(cur, base, names, v, p) {
  const t = descend(cur, names, names.length - 1, base, p)
  const last = names[names.length - 1]
  if (t.map.has(last)) p.fail('key ' + [...base, ...names].join('.') + ' is defined twice')
  t.map.set(last, v)
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = table()
  let cur = root
  let curPath = []
  lines.forEach((line, idx) => {
    const p = new LineParser(line)
    try {
      p.ws()
      const c = p.peek()
      if (c === undefined || c === '#' || c === ';') return
      if (c === '[') {
        p.i++
        const isArr = p.peek() === '['
        if (isArr) p.i++
        p.ws()
        const names = p.dotted()
        p.ws()
        if (p.peek() !== ']') p.fail('unterminated table header')
        p.i++
        if (isArr) {
          if (p.peek() !== ']') p.fail('unterminated table header')
          p.i++
        }
        if (!p.atEnd()) p.fail('trailing text after a table header')
        const parent = descend(root, names, names.length - 1, [], p)
        const last = names[names.length - 1]
        const path = names.join('.')
        const ex = parent.map.get(last)
        if (isArr) {
          let arr = ex
          if (!ex) { arr = { t: 'array', items: [], aot: true }; parent.map.set(last, arr) }
          else if (ex.t !== 'array' || !ex.aot) p.fail(path + ' is not an array of tables')
          cur = table()
          arr.items.push(cur)
        } else {
          if (!ex) { cur = table(); parent.map.set(last, cur) }
          else if (ex.t !== 'table') p.fail(path + ' is not a table')
          else if (ex.header) p.fail('table ' + path + ' is defined twice')
          else cur = ex
          cur.header = true
        }
        curPath = names
        return
      }
      const names = p.dotted()
      p.ws()
      if (p.peek() !== '=') p.fail('expected key = value')
      p.i++
      const v = p.value()
      if (!p.atEnd()) p.fail('trailing text after a value')
      assign(cur, curPath, names, v, p)
    } catch (e) {
      if (e.isConfigError) e.line = idx + 1
      throw e
    }
  })
  return root
}
